+    test('multi-item lists: any single active branch match wins (2+ items, not just the first)', function () {
+        var runs = [
+            run('completed', { branch: 'ai/gh-1', updatedAt: '2026-10-18T07:00:00.000Z' }),
+            run('in_progress', { branch: BRANCH, head: HEAD_OLD })
