+
+var guard = loadModule('js/common/branchLegGuard.js', makeRequire({}), {});
+
+var LEG_PATH = '.github/workflows/ai-teammate.yml';
+var OTHER_PATH = '.github/workflows/quality.yml';
+var BRANCH = 'ai/gh-1000';
