+        var runs = [run('completed', { head: HEAD_OLD, updatedAt: '2026-10-18T08:04:00.000Z' })];
+        assert.notOk(guard.hasActiveLegRunOnBranch(runs, BRANCH, { nowMs: NOW_MS }));
+    });
