function collectActiveWorkflowRuns(scm, workflowFile) {
    if (!scm || typeof scm.listWorkflowRuns !== 'function') return { count: 0, summaries: [] };

    var statuses = ['queued', 'in_progress', 'waiting', 'pending'];
